// Phlebotomy Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: the reasons behind the order of draw, additives and handling.
import {q, mix} from './q.js';
const MC='McCall, Phlebotomy Essentials', BM='Booth & Mundt, Phlebotomy: A Competency Based Approach';
const DRAW='Obtaining Blood Samples', PROC='Specimen Collection & Processing', TIME='Time Management & Assignment Organization', COMM='Professional Communications', CLER='Clerical Skills & Duties', SAFE='Safety Standards & Procedures', LEGAL='Legal, Ethical, & Professional Considerations', TERM='Terminology, Anatomy, & Physiology';

export default {
 id:'phlebotomy-1',
 event:'Phlebotomy',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'McCall’s Phlebotomy Essentials and Booth & Mundt’s Phlebotomy: A Competency Based Approach',
 plan:[{area:DRAW,weight:42},{area:PROC,weight:16},{area:TIME,weight:8},{area:COMM,weight:4},{area:CLER,weight:4},{area:SAFE,weight:10},{area:LEGAL,weight:8},{area:TERM,weight:8}],
 questions:mix([
  q(DRAW,'Using the CLSI order of draw for evacuated tubes, which tube is filled immediately after the blood culture bottles?','Light blue (citrate)',['Red (no additive)','Green (heparin)','Lavender (EDTA)'],'A','The order is blood cultures, light blue (citrate), red/gold (serum), green (heparin), lavender (EDTA), then gray (fluoride/oxalate). Coagulation tubes come early to avoid contamination with clot activator or other additives.',MC),
  q(DRAW,'Why is the lavender EDTA tube drawn after the green and serum tubes?','EDTA carryover alters potassium and calcium',['EDTA clots the blood in the next tube','EDTA destroys glucose in later tubes','EDTA must be filled when vein pressure is lowest'],'C','K2EDTA contains potassium and binds calcium. If it carries over into a chemistry tube, results can show falsely high potassium and falsely low calcium.',MC),
  q(DRAW,'Why must a light blue sodium citrate tube be completely filled?','To keep the 9:1 blood-to-anticoagulant ratio',['To prevent the blood from clotting too fast','To provide enough serum for testing','To protect the sample from light'],'D','Coagulation results depend on a 9:1 ratio of blood to citrate. An underfilled tube has too much anticoagulant, which falsely prolongs clotting times.',MC),
  q(DRAW,'A gray-top tube with sodium fluoride is used for glucose testing because the fluoride:','Stops cells from using up the glucose',['Clots the blood quickly for serum','Prevents platelets from clumping','Keeps the glucose from crystallizing'],'B','Blood cells keep consuming glucose after collection (glycolysis). Sodium fluoride inhibits this, preserving the glucose level for up to several days.',MC),
  q(DRAW,'Why should a tourniquet stay on for no longer than 1 minute?','Longer use causes hemoconcentration',['Longer use makes the vein collapse permanently','The tourniquet loses tension after a minute','Longer use raises the patient’s blood pressure'],'A','Prolonged tourniquet time forces plasma into the tissues and concentrates cells, proteins and some analytes, which can falsely raise results such as potassium and cholesterol.',MC),
  q(DRAW,'How far above the venipuncture site should the tourniquet be placed?','3 to 4 inches',['1 inch','6 to 8 inches','10 to 12 inches'],'C','A tourniquet 3–4 inches above the site obstructs venous flow enough to make veins prominent without blocking arterial flow.',MC),
  q(DRAW,'At what angle should the needle enter the skin for a routine venipuncture?','15 to 30 degrees',['5 to 10 degrees','45 to 60 degrees','90 degrees'],'D','An angle of 15–30 degrees, bevel up, allows the needle to enter the vein without going through it. Too steep an angle risks passing through the back wall.',MC),
  q(DRAW,'Why is the median cubital vein the first choice for venipuncture?','It is well anchored and away from major nerves',['It is the largest vein in the hand','It lies directly over the brachial artery','It is the vein closest to the heart'],'B','The median cubital vein is large, well anchored, usually easy to find and less painful, and it is not near major nerves. The basilic vein is a last choice because it lies near the median nerve and brachial artery.',MC),
  q(DRAW,'After cleaning the site with 70% isopropyl alcohol, why must it air dry before the puncture?','Wet alcohol stings and can hemolyze the sample',['Drying makes the vein rise to the surface','Alcohol must evaporate to stop bleeding','Wet alcohol dissolves the needle coating'],'D','Letting the alcohol dry for about 30 seconds completes its antiseptic action and prevents a burning sensation and red cell hemolysis. Fanning or blowing on the site recontaminates it.',MC),
  q(DRAW,'Where on an infant’s foot should a heel puncture be performed?','The outer edges of the heel’s bottom',['The back curve of the heel above the pad','The center of the heel pad','The arch of the foot'],'A','Punctures on the outer sides of the bottom of the heel avoid the calcaneus bone, nerves and arteries. The back curve and center of the heel risk bone injury and infection.',MC),
  q(DRAW,'In a capillary puncture, why is the EDTA (lavender) microtube collected first?','Platelets begin clumping quickly at the site',['EDTA needs the warmest blood','It prevents tissue fluid in later tubes','EDTA tubes need the largest volume'],'C','The capillary order of draw differs from venipuncture: EDTA comes first so the hematology sample is collected before platelets clump and alter counts.',MC),
  q(DRAW,'Why is the first drop of blood wiped away during a capillary puncture?','It contains tissue fluid that can affect results',['It is too thick to flow into a microtube','It contains alcohol from the skin','It carries bacteria from the lancet'],'A','The first drop may contain excess tissue fluid and residual alcohol, which can dilute the sample and hemolyze cells.',BM),
  q(DRAW,'Why are blood culture bottles collected first in the order of draw?','To prevent contamination of the culture',['Because they need the warmest blood','Because they hold the largest volume','Because they contain no additive'],'B','Collecting cultures first keeps them from being contaminated by microorganisms or additives that may be on the stoppers of other tubes.',MC),
  q(DRAW,'A winged (butterfly) set is used, and the first tube needed is a light blue citrate tube. Why is a discard tube drawn first?','So the citrate tube fills to the full line',['To remove clotted blood from the vein','To flush out the antiseptic','To check that the needle is inside the vein'],'D','Air in the tubing would take up space in the first tube, leaving the citrate tube underfilled and the ratio incorrect. A discard tube (plain red or another citrate tube) fills that space first.',MC),
  q(DRAW,'Which step helps prevent a hematoma at the end of a venipuncture?','Release the tourniquet before removing the needle',['Have the patient bend the arm after the draw','Remove the needle before releasing the tourniquet','Massage the site right after the draw'],'C','If the tourniquet is still on, pressure in the vein forces blood into the tissue when the needle is removed. Bending the arm can also reopen the site.',MC),
  q(DRAW,'During a draw, the patient says they feel faint and becomes pale. What should the phlebotomist do first?','Remove the tourniquet and needle',['Continue until the last tube is filled','Have the patient stand and walk','Give the patient a drink of water'],'B','Stop the procedure immediately: release the tourniquet, remove the needle, apply pressure, lower the patient’s head and call for help. Never use ammonia inhalants.',MC),
  q(DRAW,'Why should blood not be drawn from the arm on the same side as a mastectomy?','Lymph drainage is impaired on that side',['The veins on that side are always collapsed','The arm has too few red blood cells','The patient cannot feel pain on that side'],'A','Removing lymph nodes impairs lymph drainage (lymphostasis), so the arm is prone to swelling and infection and test results may be affected.',MC),
  q(DRAW,'A patient has an IV running in the left forearm, and the right arm cannot be used. What is the correct approach?','Have the IV stopped 2 minutes; draw below it',['Draw directly from the IV catheter','Draw above the IV without stopping it','Draw from the IV site after removing the tape'],'D','Drawing below an IV after it has been stopped for at least 2 minutes reduces dilution by IV fluid. Note on the requisition that the sample came from an arm with an IV.',MC),
  q(DRAW,'How many times should a light blue sodium citrate tube be gently inverted after collection?','3 to 4 times',['5 times','8 to 10 times','It should not be inverted'],'A','Citrate tubes need 3–4 gentle inversions. Serum tubes with clot activator need 5, and EDTA and most other additive tubes need 8–10. Shaking causes hemolysis.',MC),
  q(DRAW,'A vein rolls away from the needle. What technique helps prevent this?','Pull the skin taut below the site',['Insert the needle at a steeper angle','Tighten the tourniquet for longer','Tap the vein firmly before inserting'],'C','Holding the skin taut with the thumb 1–2 inches below the site keeps the vein from moving. Steeper angles risk going through the vein.',MC),
  q(DRAW,'Blood flow stops during a draw. Which action should be avoided because it can injure a nerve?','Probing blindly from side to side for the vein',['Slightly advancing or withdrawing the needle','Trying a new tube in case of lost vacuum','Checking that the bevel is not against the wall'],'B','Small adjustments are acceptable, but lateral probing can damage nerves and arteries. If the vein cannot be found, remove the needle and try another site.',MC),
  q(PROC,'How long should a serum tube with clot activator stand before it is centrifuged?','About 30 minutes',['About 2 minutes','About 2 hours','Overnight'],'D','Blood must clot completely before centrifuging; this takes about 30–60 minutes at room temperature, less with clot activators. Spinning too early leaves fibrin in the serum.',MC),
  q(PROC,'Which specimen must be protected from light during transport?','Bilirubin',['Potassium','Hemoglobin','Cholesterol'],'C','Bilirubin breaks down in light, so the tube is wrapped in foil or placed in an amber container.',MC),
  q(PROC,'An ammonia specimen is collected. How should it be transported?','In an ice-water slurry',['At body temperature','Wrapped in foil','At room temperature'],'A','Ammonia and lactic acid levels rise as cells keep metabolizing after collection. Chilling the sample in ice water slows metabolism.',MC),
  q(PROC,'A cold agglutinin specimen must be kept at body temperature (37 °C) until it is processed. Why?','The antibodies bind red cells as it cools',['The serum freezes at room temperature','Cooling destroys the antibodies','Warmth prevents bacterial growth'],'B','Cold agglutinins bind to red blood cells at cold temperatures. If the sample cools, they attach to the cells and are removed with the clot, giving a falsely low result.',MC),
  q(PROC,'A hemolyzed specimen will give a falsely high result for which test?','Potassium',['Sodium','Glucose','Calcium'],'D','Red blood cells contain much more potassium than plasma. When cells rupture, potassium leaks out and raises the measured level.',MC),
  q(PROC,'A patient is scheduled for a fasting glucose and lipid panel. How long should the patient fast beforehand?','8 to 12 hours',['1 to 2 hours','4 to 6 hours','24 hours'],'C','Fasting for 8–12 hours (water allowed) gives a stable baseline. Recent food raises glucose and triglycerides.',MC),
  q(PROC,'In an oral glucose tolerance test, when does the timing for each post-drink specimen begin?','When the patient finishes the glucose drink',['When the patient starts the glucose drink','When the fasting specimen is collected','When the patient arrives at the lab'],'A','Timed specimens are collected at set intervals after the patient finishes the glucose beverage, which should be consumed within about 5 minutes.',MC),
  q(PROC,'Before running a centrifuge, what must be done?','Balance it with equal tubes opposite each other',['Fill every empty slot with a water tube','Leave the lid open to vent heat','Spin each patient’s tubes separately'],'B','An unbalanced centrifuge vibrates, can break tubes and can be damaged. Tubes of equal volume are placed opposite one another, and the lid stays closed while it spins.',MC),
  q(TIME,'A phlebotomist receives four requests at once. Which should be collected first?','A STAT request',['A routine morning draw','An ASAP request','A timed request due in two hours'],'D','STAT means immediately, usually for emergencies. Timed requests are collected as close to the stated time as possible, ASAP requests next, and routine requests last.',MC),
  q(TIME,'When should a trough level for a drug such as vancomycin be drawn?','Just before the next dose is given',['Right after the dose finishes infusing','At any time during the day','Exactly 6 hours after the last dose'],'A','The trough is the lowest drug level, just before the next dose. The peak is drawn when the level is highest, shortly after the dose.',MC),
  q(TIME,'Why are cortisol specimens often requested at specific times, such as 8 a.m. and 4 p.m.?','Cortisol levels change during the day',['Cortisol breaks down within an hour','The lab runs cortisol only twice a day','Meals change cortisol results'],'C','Cortisol is highest in the morning and lower in the afternoon, so results must be interpreted against the time of collection.',MC),
  q(TIME,'A phlebotomist arrives for a fasting draw and finds the patient eating breakfast. What should be done?','Notify the nurse before collecting',['Draw the specimen without mentioning it','Wait 30 minutes and then draw','Draw only the tests that do not require fasting'],'B','A non-fasting specimen gives misleading results. The nurse or provider decides whether to reschedule or proceed, and any collection should be labeled as non-fasting.',MC),
  q(COMM,'A competent adult patient refuses to have blood drawn. What should the phlebotomist do?','Respect the refusal and notify the nurse',['Ask a coworker to hold the patient’s arm','Draw quickly before the patient changes their mind','Leave without telling anyone'],'D','A competent patient has the right to refuse. The phlebotomist can explain the importance of the test, but if the patient still refuses, the nurse or provider is informed and the refusal is documented.',MC),
  q(COMM,'A patient does not speak English and appears confused about the procedure. What is the best action?','Use a qualified interpreter',['Ask a family member who is a child to translate','Speak louder and use gestures','Proceed because consent is implied'],'A','A qualified medical interpreter ensures the patient understands and can give informed consent. Using children or untrained family members risks errors and privacy problems.',MC),
  q(CLER,'When should specimen tubes be labeled?','At the bedside, right after collection',['Before entering the patient’s room','After returning to the laboratory','Before the needle is inserted'],'C','Labeling immediately after collection, in the patient’s presence, prevents mix-ups. Prelabeling tubes increases the risk of putting blood in the wrong patient’s tube.',MC),
  q(CLER,'Besides the patient’s name and ID number, which information must be on a specimen label?','Date, time and collector’s initials',['The patient’s insurance ID number','The patient’s diagnosis','The room temperature'],'B','Labels typically include the patient’s full name, identification number, date of birth, date and time of collection, and the collector’s initials or ID.',MC),
  q(SAFE,'A phlebotomist is stuck by a used needle. What should be done first?','Wash the site with soap and water',['Squeeze the site to make it bleed','Apply bleach to the wound','Finish the shift and report it later'],'D','Immediately wash the site with soap and water, then report the exposure right away so testing and post-exposure treatment can begin quickly.',MC),
  q(SAFE,'When should the safety feature on a venipuncture needle be activated?','Right after the needle is withdrawn',['After returning to the laboratory','After the needle is recapped','Only if the needle is contaminated'],'A','Activating the safety device right away, with one hand, protects against needlesticks. Needles are never recapped by hand.',MC),
  q(SAFE,'When should a sharps container be replaced?','When it is about three-quarters full',['When it is completely full','Once a month','Only when it can no longer close'],'B','Overfilled containers increase the risk of needlesticks from protruding sharps. Containers are sealed and replaced at the fill line, about three-quarters full.',MC),
  q(SAFE,'A patient has a latex allergy. Which change is needed?','Use a latex-free tourniquet and gloves',['Use a thicker latex tourniquet','Apply the tourniquet over the patient’s sleeve','Skip the tourniquet entirely'],'C','Latex exposure can cause reactions ranging from rash to anaphylaxis. All supplies that touch the patient, including tourniquets, gloves and bandages, must be latex-free.',MC),
  q(SAFE,'When should hand hygiene be performed during patient collections?','Before and after each patient contact',['Only after removing gloves at the end of the shift','Only when hands look dirty','Only before drawing patients in isolation'],'D','Hand hygiene before and after every patient, and after glove removal, prevents the spread of infection. Gloves do not replace hand hygiene.',MC),
  q(LEGAL,'A patient clearly refuses, but a phlebotomist draws the blood anyway. What legal wrong has occurred?','Battery',['Slander','Malpractice insurance fraud','Breach of contract'],'A','Battery is touching a person without consent. Drawing blood after a clear refusal is battery even if no injury occurs.',MC),
  q(LEGAL,'A patient’s friend asks the phlebotomist for the patient’s test results. What should the phlebotomist do?','Decline; sharing them violates HIPAA',['Share results only if they are normal','Share results if the friend is an adult','Tell the friend to check the lab report'],'B','Under HIPAA, protected health information can be shared only with authorized people. Phlebotomists also generally do not give results to anyone; results come from the provider.',MC),
  q(LEGAL,'A patient silently extends an arm when the phlebotomist explains the draw. What type of consent is this?','Implied consent',['Informed written consent','Expressed verbal consent','Consent by proxy'],'C','Implied consent is shown by actions, such as offering an arm. Informed consent for higher-risk procedures is usually written.',MC),
  q(LEGAL,'A phlebotomist probes deeply and injures a nerve because of poor technique. This failure to meet the standard of care is:','Negligence',['Assault','Defamation','Invasion of privacy'],'D','Negligence is failing to provide care that a reasonable, trained person would provide, resulting in harm. Professional negligence is called malpractice.',MC),
  q(TERM,'What is the difference between serum and plasma?','Serum lacks fibrinogen',['Plasma lacks red and white blood cells','Serum contains an anticoagulant','Plasma comes from clotted blood'],'A','Plasma is the liquid part of anticoagulated blood and contains fibrinogen. Serum is the liquid left after blood clots, so its fibrinogen has been used up.',MC),
  q(TERM,'Which formed elements are most directly involved in forming a clot?','Thrombocytes',['Erythrocytes','Neutrophils','Lymphocytes'],'C','Thrombocytes (platelets) stick to injured vessel walls and to each other to form a platelet plug. Erythrocytes carry oxygen, and neutrophils and lymphocytes fight infection.',MC),
  q(TERM,'Which feature helps a phlebotomist tell a vein from an artery?','Veins have valves and no pulse',['Veins have thicker walls than arteries','Veins carry bright red, oxygen-rich blood','Veins carry blood away from the heart'],'B','Veins have thinner walls, valves and no pulse, and normally carry darker, oxygen-poor blood back to the heart. A pulsing vessel is an artery and must not be used for routine draws.',MC),
  q(TERM,'What is the first response of a blood vessel to injury in the process of hemostasis?','Vasoconstriction',['Platelet plug formation','Fibrin clot formation','Fibrinolysis'],'D','Hemostasis begins with the vessel narrowing to slow blood loss, followed by platelet plug formation, coagulation (fibrin clot) and finally fibrinolysis, which dissolves the clot.',MC)
 ],41)
};
